def design(x, model):
    terms = [np.ones(len(x)), *x.T]
    if model == 'quadratic':
        terms.extend((x[:, i] * x[:, j] for i in range(4) for j in range(i, 4)))
    if model == 'rational':
        terms.extend((x[:, i] / (1 + a * (x[:, i] - x[:, j]) ** 2) for i in range(4) for j in range(4) if i != j for a in (0.25, 1.0)))
    return np.column_stack(terms)
